"""Component: layers.15.mlp.down_proj:4935, which is layer 15's MLP hidden unit 4935 (its activation is that unit times about 1.15).

In plain terms: this unit is almost silent in running prose. It fires only inside an open
parenthesis, where it reads the pieces of a formula:
- a + or - (or * / ×) that follows a variable, as in "(x - 2)": strongly positive;
- a + or - that follows a digit: moderately positive;
- a + or - at the start of a group, as in "(-i)": zero;
- commas between arguments: positive, and single variables: mildly positive;
- digits, and quote or markup punctuation, weakly positive.
Outside any parenthesis, or inside square or curly brackets, it predicts 0.

This is a conceptual reading. It explains only about 4-5% of the unit's variance: inside
parentheses the sign and size also depend on context these rules do not model (for example,
arithmetic inside program code tends to be negative). A table of token-by-context means
would add roughly 2 points more.
"""

import re

READS = ()

ARITHMETIC = {"+", "-", "−", "–", "*", "/", "×"}
COMMAS = {",", '",', "',"}
VARIABLE = re.compile(r"\(?\s?[A-Za-z]\d?")
DIGITS = re.compile(r"\s?\d+")
PUNCTUATION = re.compile(r"[\"':{}\[\]=;^_\\]")


def weight(text, before):
    """The unit's value for a token inside an open parenthesis; `before` is the token before it."""
    word = text.strip()
    if word in ARITHMETIC:
        if before in ("(", ","):
            return 0.0
        if VARIABLE.fullmatch(before):
            return 4.0
        return 2.0
    if word in COMMAS:
        return 1.5
    if VARIABLE.fullmatch(text):
        return 1.0
    if DIGITS.fullmatch(text):
        return 0.5
    if PUNCTUATION.search(text):
        return 0.3
    return 0.2


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    # carry: the brackets still open, the document they belong to, and the previous token's text
    if carry is None or carry[1] != document:
        opened, before = [], ""
    else:
        opened, before = list(carry[0]), carry[2]
    inside_paren = bool(opened) and opened[-1] == "("
    value = weight(text, before) if inside_paren else 0.0
    for ch in text:
        if ch in "([{":
            opened.append(ch)
        elif ch in ")]}" and opened:
            opened.pop()
    return (opened, document, text), value

"""Sentence-boundary detector: layers.15.mlp.down_proj component 4965.

The component writes a "a sentence or line has just ended" signal. It is near zero on most
tokens and rises on the tokens that close a sentence or a line of prose:

- a full stop, question or exclamation mark (also 。 ？ ！ …), with any closing quote or
  bracket after it: the strongest. It grows with the length of the sentence so far, from
  about 2.5 right after a boundary to about 6 after 20 or more tokens, since a full stop
  after a word or two (an abbreviation, a list number) is a weaker boundary;
- a full stop after a digit (the "." in "3." or "1.2"): weak, about 1.6;
- a bare newline, or a token with a newline after other text: about 2.5 to 3;
- a colon or semicolon, and an end-of-turn or end-of-text marker: about 2.5;
- a discourse connective that opens a new thought (But, So, Thus, Therefore, However,
  Wait): about 2.5;
- commas, digits and ordinary words: about zero, slightly below it.

The program carries one number from token to token: how many tokens the current sentence
has run, reset at each boundary and at each new document.
"""

READS = ()

SENTENCE_END = ".!?。？！؟…"
CLOSERS = "\"'”’)]}»` \n\t\r"
LINKERS = {"but", "so", "thus", "therefore", "however", "wait"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    since = carry if (carry is not None and same_doc) else 0
    core = token.rstrip(CLOSERS)
    if token in ("<|im_end|>", "<|endoftext|>"):
        value, since = 2.6, 0
    elif core and core[-1] in SENTENCE_END:
        if core == "." and before[-1:].isdigit():
            value = 1.6
        else:
            value = min(2.5 + 0.2 * since, 6.2)
        since = 0
    else:
        since += 1
        if token.strip() == "" and "\n" in token:
            value = 3.2
        elif "\n" in token:
            value = 2.5
        elif token.rstrip().endswith((":", ";", "：")):
            value = 2.4
        elif token.strip() == ",":
            value = -0.3
        elif token.strip().lower() in LINKERS:
            value = 2.5
        else:
            value = 0.0
    return since, value

"""Layer 15 MLP hidden unit 4967 (this component reads almost only that unit), predicted
from the token just read.

The unit is diffuse: its value depends on context that a short program cannot see, so
token-level rules explain very little of its variance. This program captures the one
clear token effect: the plus sign ' +' (and '+') pushes it negative, most strongly in
algebra; '=' and '-' sit slightly positive; common function words ('the', 'of', 'for',
'with', ...) sit slightly negative. Everything else is predicted as 0.
"""

READS = ()

PLUS = {"+"}
POSITIVE_SMALL = {"=", "-"}
FUNCTION_WORDS = {"the", "of", "for", "with", "an", "not", "on", "that", "and", "in", "to", "a"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in PLUS:
        value = -0.5
    elif word in POSITIVE_SMALL:
        value = 0.07
    elif word in FUNCTION_WORDS:
        value = -0.05
    else:
        value = 0.0
    return carry, value

"""A coarse, low-confidence guess at layer 15's MLP unit 4971, from the token text alone.

This component is almost entirely one MLP hidden unit (activation ~ 1.23 * unit + 0.16).
That unit's large values are sparse and depend on context a token-text rule cannot see,
so this program only captures a faint trend, at a scale that keeps its errors small:
- a lone letter right after another lone letter (spelled-out or letter-spaced text,
  initials such as "J. A.") is weakly positive;
- any other lone letter is slightly positive;
- a whitespace-only token is slightly negative;
- everything else is 0.
"""

READS = ()


def _lone_letter(text):
    text = text.strip()
    return len(text) == 1 and text.isalpha()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if _lone_letter(cur):
        value = 0.35 if _lone_letter(prev) else 0.07
    elif cur.strip() == "":
        value = -0.1
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down_proj, component 4978: a "without / no-loss" detector.

What it does: the component is silent almost everywhere. When it fires it goes
negative on words of absence and trade-off. The strongest case is English "without"
("... can be done without sacrificing performance"). Weaker cases are the same idea in
other languages (sans, ohne, без, sem, sin, senza), verbs of keeping or losing a quality
(maintain, preserve, retain, minimize, sacrifice, lose), and plain negators (not, no,
never, nor, n't, 不, 没, 无, не). Its output direction, read through the unembedding,
is what a negative activation promotes: continuations such as "without losing",
"unchanged", "not at all", "without affecting". So a negative value means "the model
expects a 'without loss / unchanged' continuation here". Every other token gets 0.

Why these numbers: the mean activation of each group, fitted by least squares on 8,192
training rows: "without" about -2.3, its translations about -0.5, the trade-off verbs
about -0.9, the other negators and a few concession words (while, keep, still, nothing)
about -0.2.

What it leaves out: most of the variance. The component's large events (about 0.1% of
tokens) are only partly predicted by the words, and the bulk of its small values
(rms about 0.36) depends on context that no word list captures.
"""

READS = ()

WITHOUT = {"without"}
TRANSLATIONS = {"sans", "ohne", "без", "sem", "sin", "senza"}
TRADE_OFF = {
    "maintain", "maintaining", "preserve", "preserving", "retain", "retaining",
    "minimize", "sacrifice", "sacrificing", "lose", "losing", "compromising",
}
NEGATORS = {"no", "not", "never", "nor", "non", "n't", "'t", "’t", "不", "没", "沒", "无", "無", "не", "hiçbir"}
CONCESSION = {"while", "keep", "keeping", "still", "nothing", "minimal", "little"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in WITHOUT:
        value = -2.3
    elif word in TRANSLATIONS:
        value = -0.5
    elif word in TRADE_OFF:
        value = -0.9
    elif word in NEGATORS or word in CONCESSION:
        value = -0.2
    else:
        value = 0.0
    return carry, value

"""Word-level sketch of MLP hidden unit 4986 in layer 15 (the component's dominant input).

The component's activation is mostly one MLP hidden unit, scaled. Its value is not
explained by any simple rule: token identity explains about 1-2% of its variance, and
context (what came before) explains nearly nothing more. This program keeps only the
strongest word-level tendencies seen in training text:

- words that say something was already done or stated earlier ("already",
  "previously", "previous") push the value clearly negative;
- past-participle and perfect-aspect words ("been", "had", "asked", "reported",
  "shown", "made", "based") push it mildly negative;
- code and reuse words ("require", "load", "existing", "reference", "obtained",
  "incorporated") push it positive.

At each document's first token the component is essentially 0. Everything else sits at
the typical value. The values are group means fitted on training rows, not derived from
the model's computation.
"""

READS = ()

TYPICAL = -0.054
PRIOR = {" already", " previously", " previous"}
DONE = {" been", " had", " asked", " reported", " shown", " made", " based"}
REUSE = {" require", " load", " existing", " reference", " obtained", " incorporated"}
VALUE = {"prior": -0.5, "done": -0.15, "reuse": 0.3}


def group_value(word):
    if word in PRIOR:
        return VALUE["prior"]
    if word in DONE:
        return VALUE["done"]
    if word in REUSE:
        return VALUE["reuse"]
    return TYPICAL


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    first = prefix.position == 0 or doc[-1] != doc[-2]
    if first:
        return carry, 0.0
    return carry, group_value(prefix.token_strings[-1])

"""Layer 15, MLP hidden unit 4990 (read through its down_proj component), as a lexical proxy.

The unit is mostly diffuse: its activation is not explained by which token is present, nor by
the words around it. Its largest values sit on two families of words, and this program
predicts only those:
- Fallback / alternative-branch words ('else', 'Otherwise', 'default', '??'): strongly negative.
- In a line that opens an 'if' condition, the punctuation that closes the condition ('):',
  '{', ':') and the line break after it: mildly negative.
- Revisiting words ('again', 'previously', 'already', 'restore', 'modify', 'sorry', 'correct',
  'undo'): mildly positive.
Everything else predicts 0. The state 'inside an if line' is carried along the row and reset at
each document start and at each line break.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

FALLBACK = {"else", "Else", "otherwise", "Otherwise", "default", "Default", "DEFAULT", "??"}
REVISIT = {
    "again", "previously", "already", "restore", "modify", "modifications",
    "sorry", "correct", "undo",
}
CONDITION_END = {"):", "{", "):\n", "{\n", ":\n"}
IF_WORDS = {"if", "If"}


def step(carry, prefix, upstream: Mapping):
    text = prefix.token_strings[-1]
    word = text.strip()
    new_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    in_if = False if new_document else carry
    if word in FALLBACK:
        value = -0.8
    elif word in REVISIT:
        value = 0.4
    elif in_if and (word in CONDITION_END or "\n" in text):
        value = -0.3
    else:
        value = 0.0
    if word in IF_WORDS:
        in_if = True
    elif "\n" in text:
        in_if = False
    return in_if, value
